# Add a claim to a person. Validate first so a bad amount or date is a 400, not a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateClaim
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: loadPerson
loadPerson:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: build
build:
  class: net.officefloor.hq.app.claim.BuildClaim
  govern: [ transaction ]
  next: ref
# A reference another claim on the sheet has (regardless of case) is a 400 and writes nothing.
ref:
  class: net.officefloor.hq.app.claim.CheckClaimRef
  govern: [ transaction ]
  next: correction
# A correction (a negative amount) must name a settled claim of the same person: else a 400.
correction:
  class: net.officefloor.hq.app.claim.CheckCorrection
  govern: [ transaction ]
  next: closed
# A claim due by a date inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: retired
# A claim dated after its person's retirement date is a 409 and writes nothing.
retired:
  class: net.officefloor.hq.app.person.CheckClaimRetired
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: log
# The status it was saved at, with who, when and its due then.
log:
  class: net.officefloor.hq.app.claim.LogClaimStatus
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimAdded
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;

/**
 * A validated claim request. {@code date} is null when left blank: the sheet's entry date while it is set, else its today.
 * {@code corrects} is the number of the claim a correction (a negative amount) corrects; null for
 * any other claim. {@code ref} is its external reference, trimmed; null when left blank. {@code tags} are its
 * tags, each trimmed and lower-cased, repeats dropped, sorted and comma separated; null when none are given.
 */
public record ClaimInput(BigDecimal amount, LocalDate date, String note, String corrects, String ref, String tags) {
    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,15}(\\.\\d{1,2})?");
    private static final Pattern NUMBER = Pattern.compile("\\d{1,9}|.{1,190}-\\d{1,9}");

    /** A claim request checked by the claim form's rules. */
    public static ClaimInput from(ClaimRequest request) throws InvalidClaimException {
        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
        if (amount.isEmpty()) throw new InvalidClaimException("An amount is required");
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("An amount is a number with up to two decimals");
        }
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("A date is yyyy-MM-dd");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        if (note.length() > 1000) throw new InvalidClaimException("A note is at most 1000 characters");
        BigDecimal value = new BigDecimal(amount).setScale(2);
        String rawCorrects = request.corrects() == null ? "" : request.corrects().trim();
        String corrects = null;
        if (value.signum() < 0) {
            if (rawCorrects.isEmpty()) {
                throw new InvalidClaimException("A negative amount is a correction: name the claim it corrects");
            }
            if (!NUMBER.matcher(rawCorrects).matches()) {
                throw new InvalidClaimException("A correction names a claim by its number");
            }
            corrects = rawCorrects;
        } else if (!rawCorrects.isEmpty()) {
            throw new InvalidClaimException("Only a negative amount corrects a claim");
        }
        String ref = request.ref() == null ? "" : request.ref().trim();
        if (ref.length() > 200) throw new InvalidClaimException("A reference is at most 200 characters");
        String tags = tags(request.tags());
        if (tags != null && tags.length() > 2000) throw new InvalidClaimException("Tags are at most 2000 characters");
        return new ClaimInput(value, date, note, corrects, ref.isEmpty() ? null : ref, tags);
    }

    /** Comma separated tags, each trimmed and lower-cased, repeats dropped, sorted and comma separated; null when none. */
    static String tags(String raw) {
        if (raw == null) return null;
        java.util.TreeSet<String> tags = new java.util.TreeSet<>();
        for (String tag : raw.split(",")) {
            String t = tag.trim().toLowerCase(java.util.Locale.ROOT);
            if (!t.isEmpty()) tags.add(t);
        }
        return tags.isEmpty() ? null : String.join(",", tags);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateClaim {
    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> body)
            throws InvalidClaimException {
        body.set(ClaimInput.from(request));
