package net.officefloor.hq.app.template;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The claim templates store, kept per sheet, one per name. */
@Repository
public class TemplateRepository {

    private static final RowMapper<ClaimTemplate> ROW = (rs, n) -> new ClaimTemplate(rs.getString("sheet_id"),
            rs.getString("name"), rs.getBigDecimal("amount").setScale(2), rs.getString("note"));

    private final JdbcTemplate jdbc;

    public TemplateRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's templates, by name. */
    public List<ClaimTemplate> findAll(String sheetId) {
        return jdbc.query("SELECT sheet_id, name, amount, note FROM claim_template WHERE sheet_id = ? ORDER BY name",
                ROW, sheetId);
    }

    /** The sheet's template of that name, or null. */
    public ClaimTemplate find(String sheetId, String name) {
        List<ClaimTemplate> found = jdbc.query(
                "SELECT sheet_id, name, amount, note FROM claim_template WHERE sheet_id = ? AND name = ?",
                ROW, sheetId, name);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Saves the template, replacing one of the same name on its sheet. */
    public void save(ClaimTemplate t) {
        int n = jdbc.update("UPDATE claim_template SET amount = ?, note = ? WHERE sheet_id = ? AND name = ?",
                t.amount(), t.note(), t.sheetId(), t.name());
        if (n == 0) {
            jdbc.update("INSERT INTO claim_template (sheet_id, name, amount, note) VALUES (?, ?, ?, ?)",
                    t.sheetId(), t.name(), t.amount(), t.note());
        }
    }
}
package net.officefloor.hq.app.template;

import java.math.BigDecimal;

/** A claim template on a sheet: its name (trimmed), an amount with two decimals and a note. */
public record ClaimTemplate(String sheetId, String name, BigDecimal amount, String note) {
}
package net.officefloor.hq.app.template;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Saves the template, replacing the sheet's template of the same name. */
public class SaveTemplate {
    public void save(@Val TemplateInput input, @Val Sheet sheet, TemplateRepository repository,
            Out<ClaimTemplate> templateOut) {
        ClaimTemplate template = new ClaimTemplate(sheet.id(), input.name(), input.amount(), input.note());
        repository.save(template);
        templateOut.set(template);
    }
}
package net.officefloor.hq.app.template;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Records the template saved. Runs after every rule has passed, so a refused change writes nothing. */
public class AuditTemplateSaved {
    public void audit(@Val ClaimTemplate template, HttpServletRequest request, Audit audit) {
        audit.record("TEMPLATE_SAVED sheet=" + template.sheetId() + " by=" + Audit.user(request)
                + " name=" + template.name() + " amount=" + template.amount().toPlainString()
                + " note=" + template.note());
    }
}
package net.officefloor.hq.app.template;

import net.officefloor.hq.app.claim.ClaimInput;
import net.officefloor.hq.app.claim.ClaimRequest;
import net.officefloor.hq.app.claim.InvalidClaimException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A template needs a name (kept trimmed), and an amount and note the claim form would take for an undated claim. */
public class ValidateTemplate {
    public void validate(@RequestBody TemplateRequest request, Out<TemplateInput> body)
            throws InvalidTemplateException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) throw new InvalidTemplateException("A template name is required");
        if (name.length() > 200) throw new InvalidTemplateException("A template name is at most 200 characters");
        ClaimInput claim;
        try {
            claim = ClaimInput.from(new ClaimRequest(request.amount(), "", request.note(), "", "", ""));
        } catch (InvalidClaimException e) {
            throw new InvalidTemplateException(e.getMessage());
